export const envelope = [25, 42, 27];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const seatY = 7;
  const cx = 12;
  const cz = 13;

  // World theme palette extraction with safe fallbacks
  const woodPlanks = api.theme.wood?.planks ?? "minecraft:oak_planks";
  const woodLog = api.theme.wood?.log ?? "minecraft:oak_log";
  const woodStripped = api.theme.wood?.stripped ?? "minecraft:stripped_oak_log";
  const woodStairs = api.theme.wood?.stairs ?? "minecraft:oak_stairs";
  const woodSlab = api.theme.wood?.slab ?? "minecraft:oak_slab";
  const woodFence = api.theme.wood?.fence ?? "minecraft:oak_fence";
  const woodTrapdoor = api.theme.wood?.trapdoor ?? "minecraft:oak_trapdoor";
  const woodDoor = api.theme.wood?.door ?? "minecraft:oak_door";

  const stonePrimary = api.theme.stone?.primary ?? "minecraft:bricks";
  const stoneAccent = api.theme.stone?.accent ?? "minecraft:stone_bricks";
  const stoneStairs = api.theme.stone?.stairs ?? "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone?.slab ?? "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone?.wall ?? "minecraft:stone_brick_wall";

  const roofSolid = api.theme.roof?.solid ?? "minecraft:mud_bricks";
  const roofStairs = api.theme.roof?.stairs ?? "minecraft:mud_brick_stairs";
  const roofSlab = api.theme.roof?.slab ?? "minecraft:mud_brick_slab";

  const groundPlinth = api.theme.ground?.plinth ?? "minecraft:polished_andesite";
  const groundPavement = api.theme.ground?.pavement ?? "minecraft:cobblestone";

  // Helpers for block states
  function logAxis(baseLog, axis) {
    const base = baseLog.replace(/\[.*\]/, "");
    return `${base}[axis=${axis}]`;
  }

  function stairsState(baseStairs, facing, half = "bottom", shape = "straight") {
    const base = baseStairs.replace(/\[.*\]/, "");
    return `${base}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function slabType(baseSlab, type = "bottom") {
    const base = baseSlab.replace(/\[.*\]/, "");
    return `${base}[type=${type}]`;
  }

  function trapdoorState(baseTrapdoor, facing = "north", half = "bottom", open = false) {
    const base = baseTrapdoor.replace(/\[.*\]/, "");
    return `${base}[facing=${facing},half=${half},open=${open}]`;
  }

  // Track occupied columns to guarantee ground conformance
  const groundFootprint = new Map(); // key "x,z" -> lowest nominal Y

  function setBlock(x, y, z, block) {
    if (x < 0 || x >= sizeX || y < 0 || y >= sizeY || z < 0 || z >= sizeZ) return;
    api.set(x, y, z, block);
    const key = `${x},${z}`;
    const curr = groundFootprint.get(key);
    if (curr === undefined || y < curr) {
      groundFootprint.set(key, y);
    }
  }

  function octDist(dx, dz) {
    return Math.max(Math.abs(dx), Math.abs(dz), (Math.abs(dx) + Math.abs(dz)) * 0.7071);
  }

  // -------------------------------------------------------------
  // 1. BASE APRON & DYKE PLATFORM
  // -------------------------------------------------------------
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      const d = octDist(x - cx, z - cz);
      if (d <= 8.2) {
        setBlock(x, seatY, z, d > 7.4 ? groundPlinth : groundPavement);
      }
    }
  }

  // -------------------------------------------------------------
  // 2. DRAINAGE CULVERT & SCOOP WHEEL (SCHERPRAD)
  // -------------------------------------------------------------
  // Culvert race along x = 4..7 from z = 1 to z = 25
  for (let z = 1; z <= 25; z++) {
    // Water race floor
    for (let x = 4; x <= 7; x++) {
      setBlock(x, seatY - 1, z, groundPavement);
    }
    // Masonry retaining side walls
    for (let y = seatY - 1; y <= seatY + 2; y++) {
      setBlock(3, y, z, stonePrimary);
      setBlock(8, y, z, stonePrimary);
    }
    // Wall coping
    setBlock(3, seatY + 3, z, stoneSlab);
    setBlock(8, seatY + 3, z, stoneSlab);
  }

  // North Culvert Arched Outflow Hood (z = 2..5)
  for (let z = 2; z <= 5; z++) {
    setBlock(4, seatY + 3, z, stairsState(stoneStairs, "west", "bottom"));
    setBlock(5, seatY + 3, z, stoneSlab);
    setBlock(6, seatY + 3, z, stoneSlab);
    setBlock(7, seatY + 3, z, stairsState(stoneStairs, "east", "bottom"));
  }

  // Sluice Gate Mechanism at z = 5
  setBlock(3, seatY + 4, 5, logAxis(woodLog, "y"));
  setBlock(8, seatY + 4, 5, logAxis(woodLog, "y"));
  setBlock(3, seatY + 5, 5, woodFence);
  setBlock(8, seatY + 5, 5, woodFence);
  for (let x = 4; x <= 7; x++) {
    setBlock(x, seatY + 5, 5, logAxis(woodLog, "x"));
    setBlock(x, seatY + 1, 5, woodPlanks);
    setBlock(x, seatY + 2, 5, woodFence);
  }

  // Scoop Wheel (Scheprad) in Chamber (x = 5..6, z = 11..15, y = seatY..seatY+4)
  // Axle connecting through tower wall into internal gears
  for (let x = 4; x <= 11; x++) {
    setBlock(x, seatY + 2, 13, logAxis(woodLog, "x"));
  }
  setBlock(5, seatY + 2, 13, woodStripped);
  setBlock(6, seatY + 2, 13, woodStripped);

  // Scoop spokes and paddle blades
  for (let dy = -2; dy <= 2; dy++) {
    for (let dz = -2; dz <= 2; dz++) {
      const dist = Math.sqrt(dy * dy + dz * dz);
      if (dist > 0.8 && dist <= 2.2) {
        const y = seatY + 2 + dy;
        const z = 13 + dz;
        setBlock(5, y, z, woodFence);
        setBlock(6, y, z, woodTrapdoor);
      }
    }
  }

  // Inspection timber deck over the wheel chamber
  for (let z = 10; z <= 16; z++) {
    for (let x = 4; x <= 7; x++) {
      setBlock(x, seatY + 4, z, slabType(woodSlab, "top"));
    }
  }

  // -------------------------------------------------------------
  // 3. OCTAGONAL BRICK TOWER SHAFT (y = seatY to seatY + 19)
  // -------------------------------------------------------------
  for (let y = seatY; y <= seatY + 19; y++) {
    const isBase = y <= seatY + 4;
    const t = isBase ? 0 : (y - (seatY + 4)) / 15.0;
    const rOut = isBase ? 6.2 : 6.0 - t * 2.0; // from 6.2 down to 4.0
    const rIn = Math.max(1.8, rOut - 1.25);

    const isCorbelLevel = y === seatY + 11 || y === seatY + 15 || y === seatY + 19;

    for (let x = cx - 8; x <= cx + 8; x++) {
      for (let z = cz - 8; z <= cz + 8; z++) {
        const d = octDist(x - cx, z - cz);

        // Tower walls
        if (d <= rOut && d >= rIn) {
          if (y === seatY) {
            setBlock(x, y, z, groundPlinth);
          } else if (isCorbelLevel && d >= rOut - 0.4) {
            setBlock(x, y, z, stoneAccent);
          } else {
            setBlock(x, y, z, stonePrimary);
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 4. FLOORS & INTERNAL STRUCTURE
  // -------------------------------------------------------------
  // Ground floor pavement
  for (let x = cx - 5; x <= cx + 5; x++) {
    for (let z = cz - 5; z <= cz + 5; z++) {
      if (octDist(x - cx, z - cz) < 4.8) {
        setBlock(x, seatY, z, groundPavement);
      }
    }
  }

  // Intermediate wooden floors at y = seatY + 5 and y = seatY + 11
  const floorLevels = [seatY + 5, seatY + 11];
  for (const fy of floorLevels) {
    for (let x = cx - 5; x <= cx + 5; x++) {
      for (let z = cz - 5; z <= cz + 5; z++) {
        if (octDist(x - cx, z - cz) < 4.0) {
          // Leave hatch for ladder at (cx - 2, cz - 2)
          if (x === cx - 2 && z === cz - 2) continue;
          setBlock(x, fy, z, woodPlanks);
        }
      }
    }
  }

  // Vertical King Shaft (koningsspil) running through tower center
  for (let y = seatY + 1; y <= seatY + 21; y++) {
    setBlock(cx, y, cz, logAxis(woodLog, "y"));
  }

  // Lower pit gear on ground floor
  setBlock(cx + 1, seatY + 2, cz, stairsState(woodStairs, "east", "top"));
  setBlock(cx - 1, seatY + 2, cz, stairsState(woodStairs, "west", "top"));
  setBlock(cx, seatY + 2, cz + 1, stairsState(woodStairs, "south", "top"));
  setBlock(cx, seatY + 2, cz - 1, stairsState(woodStairs, "north", "top"));

  // Ladders between floors
  for (let y = seatY + 1; y <= seatY + 18; y++) {
    setBlock(cx - 2, y, cz - 2, "minecraft:ladder[facing=south]");
  }

  // -------------------------------------------------------------
  // 5. DOORS & WINDOWS
  // -------------------------------------------------------------
  // Ground Front Door (North, z = cz - 6, x = cx)
  for (let y = seatY + 1; y <= seatY + 3; y++) {
    setBlock(cx, y, cz - 6, "minecraft:air");
    setBlock(cx, y, cz - 5, "minecraft:air");
  }
  setBlock(cx, seatY + 1, cz - 6, "minecraft:oak_door[facing=north,half=lower,open=false]");
  setBlock(cx, seatY + 2, cz - 6, "minecraft:oak_door[facing=north,half=upper,open=false]");
  setBlock(cx, seatY + 4, cz - 6, stairsState(stoneStairs, "north", "bottom"));

  // Ground Back Door (South, z = cz + 6, x = cx)
  for (let y = seatY + 1; y <= seatY + 3; y++) {
    setBlock(cx, y, cz + 6, "minecraft:air");
    setBlock(cx, y, cz + 5, "minecraft:air");
  }
  setBlock(cx, seatY + 1, cz + 6, "minecraft:oak_door[facing=south,half=lower,open=false]");
  setBlock(cx, seatY + 2, cz + 6, "minecraft:oak_door[facing=south,half=upper,open=false]");
  setBlock(cx, seatY + 4, cz + 6, stairsState(stoneStairs, "south", "bottom"));

  // Arched Windows at intermediate levels
  const windowSpecs = [
    { x: cx - 5, y: seatY + 7, z: cz, facing: "west" },
    { x: cx + 5, y: seatY + 7, z: cz, facing: "east" },
    { x: cx, y: seatY + 14, z: cz - 4, facing: "north" },
    { x: cx, y: seatY + 14, z: cz + 4, facing: "south" },
  ];
  for (const win of windowSpecs) {
    setBlock(win.x, win.y, win.z, "minecraft:glass_pane");
    setBlock(win.x, win.y + 1, win.z, "minecraft:glass_pane");
    setBlock(win.x, win.y - 1, win.z, stairsState(stoneStairs, win.facing, "top"));
    setBlock(win.x, win.y + 2, win.z, stairsState(stoneStairs, win.facing, "bottom"));
  }

  // -------------------------------------------------------------
  // 6. STAGING GALLERY (STELLING) at y = seatY + 11..13
  // -------------------------------------------------------------
  const stageBeamY = seatY + 11;
  const stageDeckY = seatY + 12;
  const stageR = 7.6;

  // Cantilever radial beams & underneath diagonal braces
  const beamAngles = [0, 45, 90, 135, 180, 225, 270, 315];
  for (const deg of beamAngles) {
    const rad = (deg * Math.PI) / 180;
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);

    for (let r = 4.5; r <= stageR; r += 0.8) {
      const bx = Math.round(cx + cos * r);
      const bz = Math.round(cz + sin * r);
      setBlock(bx, stageBeamY, bz, logAxis(woodLog, Math.abs(cos) > Math.abs(sin) ? "x" : "z"));
    }

    // Diagonal support strut from tower wall
    const strutX = Math.round(cx + cos * (stageR - 1.2));
    const strutZ = Math.round(cz + sin * (stageR - 1.2));
    setBlock(strutX, stageBeamY - 1, strutZ, woodFence);
    setBlock(strutX, stageBeamY - 2, strutZ, woodFence);
    setBlock(Math.round(cx + cos * 4.2), stageBeamY - 3, Math.round(cz + sin * 4.2), stairsState(woodStairs, cos > 0 ? "west" : "east", "top"));
  }

  // Stage Deck & Perimeter Railing
  for (let x = cx - 9; x <= cx + 9; x++) {
    for (let z = cz - 9; z <= cz + 9; z++) {
      const d = octDist(x - cx, z - cz);
      if (d <= stageR && d >= 4.8) {
        setBlock(x, stageDeckY, z, slabType(woodSlab, "bottom"));

        // Perimeter fence
        if (d >= stageR - 0.7) {
          setBlock(x, stageDeckY + 1, z, woodFence);
        }
      }
    }
  }

  // Door onto the Stage at South facet (y = seatY + 12..14, z = cz + 4, x = cx)
  for (let y = stageDeckY + 1; y <= stageDeckY + 3; y++) {
    setBlock(cx, y, cz + 4, "minecraft:air");
    setBlock(cx, y, cz + 5, "minecraft:air");
  }
  setBlock(cx, stageDeckY + 1, cz + 5, "minecraft:oak_door[facing=south,half=lower,open=false]");
  setBlock(cx, stageDeckY + 2, cz + 5, "minecraft:oak_door[facing=south,half=upper,open=false]");

  // -------------------------------------------------------------
  // 7. ROTATING THATCHED CAP (KAP) (y = seatY + 19 to seatY + 26)
  // -------------------------------------------------------------
  const capBaseY = seatY + 19;
  // Wooden / Stone slip ring (kruiwerk)
  for (let x = cx - 5; x <= cx + 5; x++) {
    for (let z = cz - 5; z <= cz + 5; z++) {
      const d = octDist(x - cx, z - cz);
      if (d <= 4.4 && d >= 3.6) {
        setBlock(x, capBaseY, z, stoneAccent);
      }
    }
  }

  // Boat-shaped Ogee Thatched Cap Body
  const czCap = cz - 0.5;
  const capHeight = 7;

  for (let h = 0; h <= capHeight; h++) {
    const y = capBaseY + 1 + h;
    const t = h / capHeight;
    const rx = 3.8 * (1.0 - t * 0.85);
    const rzFront = 4.5 * (1.0 - t * 0.65);
    const rzBack = 5.2 * (1.0 - t * 0.75);

    for (let x = cx - 5; x <= cx + 5; x++) {
      for (let z = cz - 7; z <= cz + 7; z++) {
        const dx = (x - cx) / rx;
        const dz = (z < czCap) ? (z - czCap) / rzFront : (z - czCap) / rzBack;
        const dCap = Math.sqrt(dx * dx + dz * dz);

        if (dCap <= 1.05) {
          if (h === capHeight) {
            // Ridge Line
            setBlock(x, y, z, slabType(roofSlab, "bottom"));
          } else if (dCap >= 0.72) {
            // Roof Shell
            if (z === Math.round(czCap - rzFront) && h <= 3) {
              // Front Timber Breast (Borst)
              setBlock(x, y, z, woodStripped);
            } else {
              setBlock(x, y, z, (h === 0 || dCap > 0.95) ? roofStairs : roofSolid);
            }
          } else if (h === 0) {
            // Cap floor deck
            setBlock(x, y, z, woodPlanks);
          }
        }
      }
    }
  }

  // Cap Ridge Finials & Weathervane Mast
  for (let z = cz - 3; z <= cz + 2; z++) {
    setBlock(cx, capBaseY + capHeight + 1, z, slabType(stoneSlab, "bottom"));
  }
  setBlock(cx, capBaseY + capHeight + 2, cz - 1, woodFence);
  setBlock(cx, capBaseY + capHeight + 3, cz - 1, stoneWall);
  setBlock(cx, capBaseY + capHeight + 4, cz - 1, "minecraft:iron_bars");

  // -------------------------------------------------------------
  // 8. WINDSHAFT, HUB & 4 MASSIVE LATTICE SAILS (WIEKEN)
  // -------------------------------------------------------------
  const hubY = seatY + 22;
  const hubZ = cz - 7;

  // Windshaft (bovenas) extending from cap center forward
  for (let z = cz - 3; z >= hubZ; z--) {
    setBlock(cx, hubY, z, logAxis(woodLog, "z"));
  }
  // Iron Hub Block (askop)
  setBlock(cx, hubY, hubZ, stoneAccent);

  // Sail Arm Length = 9 blocks (spanning diameter ~19 blocks)
  const sailLen = 9;

  // 1. TOP SAIL ARM (+Y)
  for (let i = 1; i <= sailLen; i++) {
    const sy = hubY + i;
    setBlock(cx, sy, hubZ, logAxis(woodLog, "y"));
    // Lattice crossbars on East side (+X)
    setBlock(cx + 1, sy, hubZ, woodFence);
    setBlock(cx + 2, sy, hubZ, woodTrapdoor);
    // Unfurled Canvas on mid section
    if (i >= 2 && i <= 8) {
      setBlock(cx + 1, sy, hubZ, "minecraft:white_wool");
    }
    // Leading edge windboard on West side (-X)
    setBlock(cx - 1, sy, hubZ, trapdoorState(woodTrapdoor, "east", "bottom", false));
  }

  // 2. BOTTOM SAIL ARM (-Y)
  for (let i = 1; i <= sailLen; i++) {
    const sy = hubY - i;
    setBlock(cx, sy, hubZ, logAxis(woodLog, "y"));
    // Lattice crossbars on West side (-X)
    setBlock(cx - 1, sy, hubZ, woodFence);
    setBlock(cx - 2, sy, hubZ, woodTrapdoor);
    // Unfurled Canvas
    if (i >= 2 && i <= 8) {
      setBlock(cx - 1, sy, hubZ, "minecraft:white_wool");
    }
    // Leading edge windboard on East side (+X)
    setBlock(cx + 1, sy, hubZ, trapdoorState(woodTrapdoor, "west", "bottom", false));
  }

  // 3. WEST SAIL ARM (-X)
  for (let i = 1; i <= sailLen; i++) {
    const sx = cx - i;
    setBlock(sx, hubY, hubZ, logAxis(woodLog, "x"));
    // Lattice crossbars on Top side (+Y)
    setBlock(sx, hubY + 1, hubZ, woodFence);
    setBlock(sx, hubY + 2, hubZ, woodTrapdoor);
    // Unfurled Canvas
    if (i >= 2 && i <= 8) {
      setBlock(sx, hubY + 1, hubZ, "minecraft:white_wool");
    }
    // Leading edge windboard on Bottom side (-Y)
    setBlock(sx, hubY - 1, hubZ, trapdoorState(woodTrapdoor, "north", "top", false));
  }

  // 4. EAST SAIL ARM (+X)
  for (let i = 1; i <= sailLen; i++) {
    const sx = cx + i;
    setBlock(sx, hubY, hubZ, logAxis(woodLog, "x"));
    // Lattice crossbars on Bottom side (-Y)
    setBlock(sx, hubY - 1, hubZ, woodFence);
    setBlock(sx, hubY - 2, hubZ, woodTrapdoor);
    // Unfurled Canvas
    if (i >= 2 && i <= 8) {
      setBlock(sx, hubY - 1, hubZ, "minecraft:white_wool");
    }
    // Leading edge windboard on Top side (+Y)
    setBlock(sx, hubY + 1, hubZ, trapdoorState(woodTrapdoor, "south", "bottom", false));
  }

  // -------------------------------------------------------------
  // 9. CAP TURNING TAIL STRUCTURE (STAARTWERK & KRUIHASPEL)
  // -------------------------------------------------------------
  // Main tail pole sloping from cap rear (y=seatY+22, z=cz+5) to stage (y=seatY+12, z=cz+11)
  const tailSteps = 6;
  for (let s = 0; s <= tailSteps; s++) {
    const t = s / tailSteps;
    const ty = Math.round((seatY + 23) - t * 10);
    const tz = Math.round((cz + 4) + t * 7);
    setBlock(cx, ty, tz, logAxis(woodLog, "z"));
  }

  // Diagonal lateral braces (spruiten) from cap sides to tail pole
  for (let s = 1; s <= 4; s++) {
    const t = s / 4;
    const by = Math.round((seatY + 22) - t * 4);
    const bz = Math.round((cz + 2) + t * 6);
    const bxOffset = Math.round(3.5 * (1 - t));
    setBlock(cx - bxOffset, by, bz, woodFence);
    setBlock(cx + bxOffset, by, bz, woodFence);
  }

  // Winch Wheel (kruilier) at bottom of the tail pole
  setBlock(cx, stageDeckY + 1, cz + 11, woodFence);
  setBlock(cx, stageDeckY + 2, cz + 11, woodTrapdoor);
  setBlock(cx - 1, stageDeckY + 1, cz + 11, woodFence);
  setBlock(cx + 1, stageDeckY + 1, cz + 11, woodFence);

  // -------------------------------------------------------------
  // 10. GROUND CONFORMANCE PASS (RULE 6)
  // -------------------------------------------------------------
  // Fill foundations downwards to heightAt(x, z) on slopes/shores,
  // or reinforce upward if terrain rises above nominal seat plane.
  for (const [key, nominalBaseY] of groundFootprint.entries()) {
    const [sx, sz] = key.split(",").map(Number);
    const gh = api.heightAt(sx, sz);
    const terrainY = Math.max(0, Math.min(sizeY - 1, Math.round(seatY + gh)));

    if (terrainY < nominalBaseY) {
      // Ground falls away: step foundation down to meet terrain
      for (let y = terrainY; y < nominalBaseY; y++) {
        const d = octDist(sx - cx, sz - cz);
        const mat = d <= 6.5 ? stonePrimary : groundPlinth;
        api.set(sx, y, sz, mat);
      }
    } else if (terrainY > nominalBaseY && terrainY < sizeY) {
      // Ground rises: extend wall / plinth upward to meet rising ground
      for (let y = nominalBaseY; y <= terrainY; y++) {
        const d = octDist(sx - cx, sz - cz);
        if (d >= 4.5 && d <= 7.5) {
          api.set(sx, y, sz, stonePrimary);
        }
      }
    }
  }

  // Return complete landmark metadata
  return {
    name: "great_brick_windmill",
    seatY,
    anchors: {
      front: [cx, seatY, 0],
      door: [cx, seatY + 1, cz - 6],
      culvert: [5, seatY, 2],
    },
    interiors: [
      {
        min: [cx - 3, seatY + 1, cz - 3],
        max: [cx + 3, seatY + 4, cz + 3],
        kind: "vault",
      },
      {
        min: [cx - 2, seatY + 12, cz - 2],
        max: [cx + 2, seatY + 16, cz + 2],
        kind: "quarters",
      },
    ],
  };
}
